namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int LoyaltyCapCents = 2_000;

    public static int LoyaltyPartCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(subtotalCents * RatePercent(tier) / 100, LoyaltyCapCents);

    public static int TotalDiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyPart = LoyaltyPartCents(subtotalCents, tier);
        var promoPart = PromoCode.From(promoCode).DiscountCents(subtotalCents - loyaltyPart);
        return Math.Min(loyaltyPart + promoPart, subtotalCents);
    }

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };
}

namespace CheckoutPricing.Domain;

public readonly record struct PromoCode
{
    private const int Welcome5Cents = 500;
    private const int Summer10Percent = 10;
    private const int Summer10CapCents = 1_500;

    private readonly string? _value;

    private PromoCode(string? value) => _value = value;

    public static PromoCode From(string? value) => new(value);

    public int DiscountCents(int remainingCents)
    {
        if (Is("WELCOME5"))
        {
            return Welcome5Cents;
        }

        return Is("SUMMER10")
            ? Math.Min(remainingCents * Summer10Percent / 100, Summer10CapCents)
            : 0;
    }

    private bool Is(string code) =>
        string.Equals(_value, code, StringComparison.OrdinalIgnoreCase);
}

namespace CheckoutPricing.Domain;

public static class ShippingPolicy
{
    private const int StandardFeeCents = 490;
    private const int ExpressFeeCents = 990;
    private const int FreeStandardFromCents = 5_000;

    public static int FeeCents(int payableTotalCents, LoyaltyTier tier, bool express) =>
        express
            ? ExpressFeeCents(tier)
            : StandardFeeCents(payableTotalCents, tier);

    private static int ExpressFeeCents(LoyaltyTier tier) =>
        tier == LoyaltyTier.Platinum ? 0 : ExpressFeeCents;

    private static int StandardFeeCents(int payableTotalCents, LoyaltyTier tier) =>
        payableTotalCents >= FreeStandardFromCents || tier >= LoyaltyTier.Gold
            ? 0
            : StandardFeeCents;
}

namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int LoyaltyCapCents = 2_000;

    public static int LoyaltyPartCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(subtotalCents * RatePercent(tier) / 100, LoyaltyCapCents);

    public static int TotalDiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyPart = LoyaltyPartCents(subtotalCents, tier);
        var promoPart = PromoCode.From(promoCode).DiscountCents(subtotalCents - loyaltyPart);
        return Math.Min(loyaltyPart + promoPart, subtotalCents);
    }

    private static int RatePercent(LoyaltyTier tier) => tier switch
